#!/usr/bin/env python3
"""每套竖屏布局有自己的工具条形态（不再共用一条底部条）：

* capcut   底部 4 个（导入/文字/形状/预设）
* jianying 底部 5 个（多一个播放，切换 self.playback.playing）
* kuaishou 右侧竖排 4 个
* blurrr   顶部 3 个（播放/文字/预设）

按钮全部调用现有命令或现有 UI 状态，没有假按钮。横屏 AE 布局不画这些。
"""
from __future__ import annotations

import os
from pathlib import Path

MARKER = "EFFECTCRAFT_OURS_LAYOUT_CHROME_V1"

OLD = '        // EFFECTCRAFT_OURS_PORTRAIT_TRAY_V1 — 竖屏布局专属的底部工具条。\n        {\n            let ws = self.ui.workspace.as_str();\n            // 打开对话框时不画工具条，免得压住弹窗\n            let portrait = matches!(ws, "capcut" | "blurrr" | "kuaishou" | "jianying")\n                && self.dialog.is_none();\n            if portrait {\n                let screen = ui.ctx().content_rect();\n                let h = 58.0;\n                let bar = egui::Rect::from_min_size(\n                    egui::pos2(screen.min.x + 10.0, screen.max.y - h - 8.0),\n                    egui::vec2(screen.width() - 20.0, h),\n                );\n                let p = ui.painter();\n                p.rect_filled(bar, 14.0, egui::Color32::from_rgba_unmultiplied(12, 12, 14, 200));\n                p.rect_stroke(\n                    bar,\n                    14.0,\n                    egui::Stroke::new(1.0, egui::Color32::from_rgba_unmultiplied(255, 255, 255, 60)),\n                    egui::StrokeKind::Inside,\n                );\n                let items: [(&str, &str); 4] = [\n                    ("\\u{ff0b}", "导入"),\n                    ("T", "文字"),\n                    ("\\u{25c7}", "形状"),\n                    ("\\u{2605}", "预设"),\n                ];\n                let n = items.len() as f32;\n                let cw = bar.width() / n;\n                for (i, (glyph, label)) in items.iter().enumerate() {\n                    let cell = egui::Rect::from_min_size(\n                        egui::pos2(bar.min.x + cw * i as f32, bar.min.y),\n                        egui::vec2(cw, bar.height()),\n                    );\n                    let resp = ui.interact(\n                        cell,\n                        egui::Id::unique(("ours-tray", i as u64)),\n                        egui::Sense::click(),\n                    );\n                    let hot = resp.hovered();\n                    if hot {\n                        p.rect_filled(cell.shrink(4.0), 10.0, self.tokens.accent.gamma_multiply(0.16));\n                    }\n                    p.text(\n                        egui::pos2(cell.center().x, cell.center().y - 8.0),\n                        egui::Align2::CENTER_CENTER,\n                        *glyph,\n                        Tokens::ui(18.0),\n                        if hot { self.tokens.accent } else { self.tokens.text },\n                    );\n                    p.text(\n                        egui::pos2(cell.center().x, cell.center().y + 12.0),\n                        egui::Align2::CENTER_CENTER,\n                        *label,\n                        Tokens::ui(9.5),\n                        self.tokens.text_dim,\n                    );\n                    if resp.clicked() {\n                        match i {\n                            0 => {\n                                ui.ctx().data_mut(|d| {\n                                    d.insert_temp(egui::Id::new("ours-import-open"), true)\n                                });\n                            }\n                            1 => {\n                                let _ = crate::menus::invoke(\n                                    self,\n                                    ui.ctx(),\n                                    "layer.new",\n                                    serde_json::json!({ "text": "文字", "edit": false }),\n                                );\n                            }\n                            2 => {\n                                let _ = crate::menus::invoke(\n                                    self,\n                                    ui.ctx(),\n                                    "layer.newShape",\n                                    serde_json::json!({ "kind": "rect" }),\n                                );\n                            }\n                            _ => {\n                                ui.ctx().data_mut(|d| {\n                                    d.insert_temp(egui::Id::new("ours-preset-open"), true)\n                                });\n                            }\n                        }\n                    }\n                }\n            }\n        }'

NEW = '        // EFFECTCRAFT_OURS_LAYOUT_CHROME_V1 — 每套竖屏布局有自己的形态：\n        //   capcut        底部 4 个（导入/文字/形状/预设）\n        //   jianying      底部 5 个（多一个播放）\n        //   kuaishou      右侧竖排 4 个\n        //   blurrr        顶部 3 个（播放/文字/预设）\n        // 按钮都调用现有命令或现有 UI 状态，不做假按钮。\n        {\n            let ws = self.ui.workspace.as_str().to_string();\n            let dialog_open = self.dialog.is_some();\n            let accent = self.tokens.accent;\n            let text_c = self.tokens.text;\n            let dim_c = self.tokens.text_dim;\n            let screen = ui.ctx().content_rect();\n            let mut fired: Option<u8> = None;\n            if !dialog_open {\n                if ws == "capcut" || ws == "jianying" {\n                    let h = 58.0;\n                    let bar = egui::Rect::from_min_size(\n                        egui::pos2(screen.min.x + 10.0, screen.max.y - h - 8.0),\n                        egui::vec2(screen.width() - 20.0, h),\n                    );\n                    ui.painter().rect_filled(\n                        bar,\n                        14.0,\n                        egui::Color32::from_rgba_unmultiplied(12, 12, 14, 205),\n                    );\n                    let n: usize = if ws == "jianying" { 5 } else { 4 };\n                    let cw = bar.width() / n as f32;\n                    for i in 0..n {\n                        let cell = egui::Rect::from_min_size(\n                            egui::pos2(bar.min.x + cw * i as f32, bar.min.y),\n                            egui::vec2(cw, bar.height()),\n                        );\n                        let (label, glyph) = match i {\n                            0 => ("导入", "\\u{ff0b}"),\n                            1 => ("文字", "T"),\n                            2 => ("形状", "\\u{25c7}"),\n                            3 => ("预设", "\\u{2605}"),\n                            _ => ("播放", "\\u{25b6}"),\n                        };\n                        let resp = ui.interact(\n                            cell,\n                            egui::Id::unique(("ours-bottom", i as u64)),\n                            egui::Sense::click(),\n                        );\n                        let hot = resp.hovered();\n                        if hot {\n                            ui.painter().rect_filled(\n                                cell.shrink(3.0),\n                                10.0,\n                                accent.gamma_multiply(0.16),\n                            );\n                        }\n                        ui.painter().text(\n                            egui::pos2(cell.center().x, cell.center().y - 7.0),\n                            egui::Align2::CENTER_CENTER,\n                            glyph,\n                            Tokens::ui(17.0),\n                            if hot { accent } else { text_c },\n                        );\n                        ui.painter().text(\n                            egui::pos2(cell.center().x, cell.center().y + 11.0),\n                            egui::Align2::CENTER_CENTER,\n                            label,\n                            Tokens::ui(9.0),\n                            dim_c,\n                        );\n                        if resp.clicked() {\n                            fired = Some(i as u8);\n                        }\n                    }\n                } else if ws == "kuaishou" {\n                    let w = 62.0;\n                    let ch = 58.0;\n                    let rail = egui::Rect::from_min_size(\n                        egui::pos2(screen.max.x - w - 6.0, screen.center().y - ch * 2.0),\n                        egui::vec2(w, ch * 4.0),\n                    );\n                    ui.painter().rect_filled(\n                        rail,\n                        16.0,\n                        egui::Color32::from_rgba_unmultiplied(12, 12, 14, 205),\n                    );\n                    for i in 0..4u64 {\n                        let cell = egui::Rect::from_min_size(\n                            egui::pos2(rail.min.x, rail.min.y + ch * i as f32),\n                            egui::vec2(w, ch),\n                        );\n                        let (label, glyph) = match i {\n                            0 => ("导入", "\\u{ff0b}"),\n                            1 => ("文字", "T"),\n                            2 => ("形状", "\\u{25c7}"),\n                            _ => ("预设", "\\u{2605}"),\n                        };\n                        let resp = ui.interact(\n                            cell,\n                            egui::Id::unique(("ours-rail", i)),\n                            egui::Sense::click(),\n                        );\n                        let hot = resp.hovered();\n                        if hot {\n                            ui.painter().rect_filled(\n                                cell.shrink(3.0),\n                                10.0,\n                                accent.gamma_multiply(0.16),\n                            );\n                        }\n                        ui.painter().text(\n                            egui::pos2(cell.center().x, cell.center().y - 7.0),\n                            egui::Align2::CENTER_CENTER,\n                            glyph,\n                            Tokens::ui(17.0),\n                            if hot { accent } else { text_c },\n                        );\n                        ui.painter().text(\n                            egui::pos2(cell.center().x, cell.center().y + 11.0),\n                            egui::Align2::CENTER_CENTER,\n                            label,\n                            Tokens::ui(9.0),\n                            dim_c,\n                        );\n                        if resp.clicked() {\n                            fired = Some(i as u8);\n                        }\n                    }\n                } else if ws == "blurrr" {\n                    let strip = egui::Rect::from_min_size(\n                        egui::pos2(screen.min.x + 8.0, screen.min.y + 40.0),\n                        egui::vec2(screen.width() - 16.0, 42.0),\n                    );\n                    ui.painter().rect_filled(\n                        strip,\n                        12.0,\n                        egui::Color32::from_rgba_unmultiplied(12, 12, 14, 190),\n                    );\n                    let cw = strip.width() / 3.0;\n                    for i in 0..3u64 {\n                        let cell = egui::Rect::from_min_size(\n                            egui::pos2(strip.min.x + cw * i as f32, strip.min.y),\n                            egui::vec2(cw, strip.height()),\n                        );\n                        let (label, glyph) = match i {\n                            0 => ("播放", "\\u{25b6}"),\n                            1 => ("文字", "T"),\n                            _ => ("预设", "\\u{2605}"),\n                        };\n                        let resp = ui.interact(\n                            cell,\n                            egui::Id::unique(("ours-top", i)),\n                            egui::Sense::click(),\n                        );\n                        let hot = resp.hovered();\n                        if hot {\n                            ui.painter().rect_filled(\n                                cell.shrink(3.0),\n                                10.0,\n                                accent.gamma_multiply(0.16),\n                            );\n                        }\n                        ui.painter().text(\n                            egui::pos2(cell.center().x, cell.center().y - 7.0),\n                            egui::Align2::CENTER_CENTER,\n                            glyph,\n                            Tokens::ui(17.0),\n                            if hot { accent } else { text_c },\n                        );\n                        ui.painter().text(\n                            egui::pos2(cell.center().x, cell.center().y + 11.0),\n                            egui::Align2::CENTER_CENTER,\n                            label,\n                            Tokens::ui(9.0),\n                            dim_c,\n                        );\n                        if resp.clicked() {\n                            fired = Some(if i == 0 { 4 } else if i == 1 { 1 } else { 3 });\n                        }\n                    }\n                }\n            }\n            match fired {\n                Some(0) => {\n                    ui.ctx()\n                        .data_mut(|d| d.insert_temp(egui::Id::new("ours-import-open"), true));\n                }\n                Some(1) => {\n                    let _ = crate::menus::invoke(\n                        self,\n                        ui.ctx(),\n                        "layer.new",\n                        serde_json::json!({ "text": "文字", "edit": false }),\n                    );\n                }\n                Some(2) => {\n                    let _ = crate::menus::invoke(\n                        self,\n                        ui.ctx(),\n                        "layer.newShape",\n                        serde_json::json!({ "kind": "rect" }),\n                    );\n                }\n                Some(3) => {\n                    ui.ctx()\n                        .data_mut(|d| d.insert_temp(egui::Id::new("ours-preset-open"), true));\n                }\n                Some(4) => {\n                    self.playback.playing = !self.playback.playing;\n                    ui.ctx().request_repaint();\n                }\n                _ => {}\n            }\n        }'


def main() -> None:
    root = Path(os.environ["EFFECTCRAFT_DIR"]).resolve()
    frame = root / "crates/ui-egui/src/app/frame.rs"
    src = frame.read_text(encoding="utf-8")
    if MARKER in src:
        print("per-brand chrome already present")
        return
    if src.count(OLD) != 1:
        raise SystemExit(f"anchor: {{src.count(OLD)}}")
    frame.write_text(src.replace(OLD, NEW, 1), encoding="utf-8")
    print("per-brand chrome: capcut/jianying bottom, kuaishou rail, blurrr top strip")


if __name__ == "__main__":
    main()
